@code {
    private AppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool validationPassed;
    private bool appointmentBooked;
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Manual validation of step 1 fields
        editContext ??= new EditContext(Model);

        var isValid = true;
        serverErrors.Clear();

        if (string.IsNullOrWhiteSpace(Model.PatientName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            isValid = false;
        }

        // Validate email format
        if (!string.IsNullOrWhiteSpace(Model.Email) &&
            !System.ComponentModel.DataAnnotations.Validator.TryValidateProperty(
                Model.Email,
                new System.ComponentModel.DataAnnotations.ValidationContext(Model) { MemberName = nameof(Model.Email) },
                null))
        {
            isValid = false;
        }

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged(string value)
    {
        Model.Doctor = value;
        Model.TimeSlot = string.Empty;
        if (!string.IsNullOrEmpty(value) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        validationPassed = false;

        // Load time slots if not loaded yet
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue && !timeSlots.Any())
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(Model.Doctor, Model.AppointmentDate.Value);
        }

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        if (errors.Any())
        {
            serverErrors = errors;
        }
        else
        {
            validationPassed = true;
        }
    }

    private void HandleSubmit()
    {
        if (validationPassed)
        {
            appointmentBooked = true;
        }
    }
}
"}

